const cds = require('@sap/cds')
const { exists } = cds.utils
const LOG = cds.log('mtx')
const [major] = cds.version.split('.').map(Number)
if (major < 9) throw new Error('@sap/cds-mtxs 3 requires @sap/cds version 9 or higher. Current version: ' + cds.version)

const cdscDefaults = Object.fromEntries(
    Object.entries(cds.env.defaults?.cdsc || {}).filter(([key]) => !key.startsWith('[') )
)
const sqlDefaults = Object.fromEntries(
    Object.entries(cds.env.defaults?.sql || {}).filter(([key]) => !key.startsWith('[') )
)

require('./srv/extensibility/linter').legacyCheck()

const main = require('./srv/config')
const inSidecar = cds.env.requires['cds.xt.ModelProviderService']?._in_sidecar === true

if (inSidecar && process.env.NODE_ENV === 'production' && !exists(main.root)) {
    throw new Error(`Invalid MTX sidecar layout: '${main.root}' is missing. Ensure the generated sidecar build output is deployed.`)
}

if (main.env.cdsc && inSidecar) {
    if (cds.env.cdsc && !(cds.env.requires['cds.xt.ModelProviderService']?.['use-local-cdsc-config'] === true)) {

        // should not be used in MTX
        delete cds.env.cdsc.tenantDiscriminator
        delete main.env.cdsc.tenantDiscriminator

        const stringifiedEnv = JSON.stringify(cds.env.cdsc)

        if (stringifiedEnv !== JSON.stringify(main.env.cdsc) && stringifiedEnv !== JSON.stringify(cdscDefaults)) {
            LOG.warn('inconsistent compiler configuration: using cds.cdsc configuration of root project')
        }
        cds.env.cdsc = main.env.cdsc
    }
} else {
    cds.env.cdsc = main.env.cdsc
}

if (inSidecar) {
    if (!(cds.env.requires['cds.xt.ModelProviderService']?.['use-root-sql-config'] === true)) {
        const stringifiedSql = JSON.stringify(cds.env.sql)

        if (stringifiedSql !== JSON.stringify(main.env.sql) && stringifiedSql !== JSON.stringify(sqlDefaults)) {
            LOG.warn('inconsistent sql configuration: using cds.sql configuration of mtx sidecar')
        }
        // LATER: cds.env.sql = main.env.sql
    } else {
        cds.env.sql = main.env.sql
    }
} else {
    cds.env.sql = main.env.sql
}

cds.once('served', async () => {
    if (cds.model.definitions['cds.xt.ModelProviderService']) return
    const { definitions } = cds.model
    const models = []

    if (cds.requires.multitenancy) {
        _serve('cds.xt.SaasProvisioningService')
        _serve('cds.xt.DeploymentService')
        _serve('cds.xt.ModelProviderService')
    }

    if (cds.requires.extensibility) {
        _serve('cds.xt.ExtensibilityService')
        _serve('cds.xt.ModelProviderService')
    }

    if (cds.requires.toggles) {
        _serve('cds.xt.ModelProviderService')
    }

    function _serve(service) {
        if (service in definitions) return
        if (cds.requires[service] === false) return
        models.push(cds.requires.kinds[service].model)
    }

    if (models.length) await cds.serve(models).in(cds.app)
})
require('./srv/plugins/common')
